-- Parzellen nach Wunsch, zweite Lieferung (Julian, 19. November): dazu
-- Nidau und Muri bei Bern (BE), Ingenbohl mit Brunnen, Einsiedeln,
-- Küssnacht, Schwyz und Arth (SZ), Altdorf (UR), Ebikon, Horw, Kriens,
-- Meggen und Luzern (LU). Brunnen ist keine Gemeinde, sondern ein Dorf in
-- Ingenbohl; gerechnet ist die ganze Gemeinde.
--
-- Der Inhalt des Ordners wird ganz ersetzt, auch Sarnen und Nidwalden:
-- Der Dienst des Bundes gibt höchstens 200 Treffer je Abfrage, und beim
-- Weiterblättern kamen Doppelte, andere fehlten (Nidau: 553 Treffer, 394
-- verschieden). Jetzt wird eine volle Kachel geviertelt statt geblättert,
-- für Parzellen und Bauzonen. Die Parzellen gehören über ihre Lage zur
-- Gemeinde, nicht über die Nummer des Grundbuchkreises (in Bern und
-- Luzern nicht die der Gemeinde). Je Gemeinde ergeben alle Parzellen die
-- Gemeindefläche, bis auf Wasser, das zu einem See gehört.

begin;

update public.wunsch_ordner
   set name = 'Über 3''000 m² in der Bauzone',
       quelle = 'Amtliche Vermessung beim Bund, Fläche aus dem Umriss, ohne Baurechte; mindestens die Hälfte der Parzelle in der Bauzone (Bauzonen Schweiz).',
       stand = '19. November 2026'
 where id = '6a1f0c3e-5b7d-4e1a-9c2f-3d8b0e4a7f19';

delete from public.wunsch_parzelle where ordner_id = '6a1f0c3e-5b7d-4e1a-9c2f-3d8b0e4a7f19';

insert into public.wunsch_parzelle (ordner_id, egrid, kanton, bfs, gemeinde, nummer, flaeche, zone, bauzone_anteil, e, n, lat, lon)
